"""The download page, and how a running copy learns it is out of date.

WHAT "LIKE A GAME" MEANS HERE. Somebody opens one address, presses one button,
gets one file, opens it, signs in. No zip, no folder of DLLs, no instructions.
And the copy already installed says so when a newer one exists, rather than
quietly staying a year behind.

WHY THESE ROUTES ARE OPEN. A download page you must sign in to see is a page
nobody can use to get the thing they sign in WITH. So /download and /api/version
carry no token - and carry nothing worth stealing either: a version number and
an installer that is useless without an account.
"""

from __future__ import annotations

import hashlib
import json
import re
from pathlib import Path
from typing import Any

from fastapi import APIRouter, HTTPException
from fastapi.responses import FileResponse, HTMLResponse

router = APIRouter()

RELEASES_DIR = Path(__file__).resolve().parent.parent / "releases"
# Tên file phải theo đúng khuôn này. Một tên tự do là một phiên bản không ai
# đọc ra được, và là một chỗ để nhét đường dẫn lạ vào.
# Hai ten. Chuong trinh doi ten thanh PantongOne, nhung nhung may dang chay
# ban cu van hoi may chu bang ten cu - va cai chung TAI ve moi la thu quyet
# dinh, khong phai ten tep. Bo ten cu di la nhung may do khong bao gio thay
# ban cap nhat nao nua, va khong co gi bao.
NAME_PATTERN = re.compile(r"^(?:PantongOne|ThaiPlasticPricing)_v(\d+)\.(\d+)\.(\d+)\.exe$")


def _versions() -> list[tuple[tuple[int, int, int], Path]]:
    if not RELEASES_DIR.is_dir():
        return []
    found = []
    for path in RELEASES_DIR.iterdir():
        match = NAME_PATTERN.match(path.name)
        if match and path.is_file():
            found.append(((int(match[1]), int(match[2]), int(match[3])), path))
    return sorted(found, reverse=True)


def latest() -> dict[str, Any] | None:
    versions = _versions()
    if not versions:
        return None
    (major, minor, patch), path = versions[0]
    return {
        "version": f"{major}.{minor}.{patch}",
        "filename": path.name,
        "size_bytes": path.stat().st_size,
        # What the app checks what it downloaded against. Without it, "update"
        # means "run whatever arrived", and a truncated download is a program
        # that will not start.
        "sha256": sha256_of(path),
        "download_url": "/download/" + path.name,
    }


_HASH_CACHE: dict[tuple[str, int, int], str] = {}


def sha256_of(path: Path) -> str:
    """The fingerprint of an installer, remembered between calls.

    Cached on (name, size, mtime): every running copy asks for this at start-up,
    and re-reading 13 MB off disk for each of them turns a version check into
    real work on a server that is also holding the factory's quotations.

    A file that is replaced changes size or mtime, so the key changes with it -
    a stale hash would be worse than none, because the app REFUSES a download
    that does not match and everybody would be stuck on the old build.
    """
    stat = path.stat()
    key = (path.name, stat.st_size, int(stat.st_mtime))
    if key not in _HASH_CACHE:
        digest = hashlib.sha256()
        with path.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
        _HASH_CACHE[key] = digest.hexdigest()
    return _HASH_CACHE[key]


@router.get("/api/version")
def version() -> dict[str, Any]:
    """What the newest installer is.

    A running copy asks this at start-up and says one line if it is behind. It
    does NOT download anything by itself: a program that replaces its own
    executable while somebody is halfway through a quotation is a program that
    loses a quotation.
    """
    newest = latest()
    if newest is None:
        return {"available": False}
    return {"available": True, **newest}


@router.get("/download/{filename}")
def download(filename: str) -> FileResponse:
    # Matched against the pattern rather than joined onto a path: "filename"
    # arrives from the internet, and ../../etc/passwd is a filename too.
    if not NAME_PATTERN.match(filename):
        raise HTTPException(status_code=404, detail="ไม่พบไฟล์ / no such file")
    path = RELEASES_DIR / filename
    if not path.is_file():
        raise HTTPException(status_code=404, detail="ไม่พบไฟล์ / no such file")
    return FileResponse(path, media_type="application/octet-stream", filename=filename)


