# Ba duong dan cho MOT trang. Nguoi ta go dia chi bang tay: pricing.../download
# va pricing.../download/ phai ra cung mot cho, khong phai mot cho va mot trang
# 404. Duong co gach cuoi khai o day TRUOC /download/{filename}, neu khong no
# roi vao nhanh tep voi ten rong.
#
# "/" IS NO LONGER ONE OF THEM. Bee, 27-08-2026: "không cần xài Exe nữa bỏ luôn
# dời hẳn lên web". The front door is the program itself now, and the installer
# page keeps the address that describes it. The page and the file both still
# answer, because a machine that already has the .exe installed is still
# syncing its drafts up through this same service, and cutting that off would
# strand whatever has not been sent yet.
@router.get("/download/", response_class=HTMLResponse)
@router.get("/download", response_class=HTMLResponse)
def page() -> HTMLResponse:
    newest = latest()
    if newest is None:
        body = '<p class="none">ยังไม่มีไฟล์ให้ดาวน์โหลด / No release has been published yet.</p>'
    else:
        size_mb = newest["size_bytes"] / (1024 * 1024)
        body = (
            '<a class="get" href="' + newest["download_url"] + '">'
            "ดาวน์โหลด / Download &nbsp;v" + newest["version"] + "</a>"
            '<p class="meta">' + newest["filename"] + " &middot; "
            + format(size_mb, ".1f") + " MB</p>"
        )
    return HTMLResponse(PAGE.replace("__BODY__", body))
